/* 1회성 백필: autoGenerated MMB 뉴스 중 imageUrl 없는 글에 원본 og:image 채우기 */
import { PrismaClient } from '@prisma/client';
import { load as cheerioLoad } from 'cheerio';

const prisma = new PrismaClient();

async function ogImage(url: string): Promise<string | undefined> {
  try {
    const res = await fetch(url, { headers: { 'User-Agent': 'mavs.kr/1.0' } });
    if (!res.ok) return undefined;
    const $ = cheerioLoad(await res.text());
    const og = $('meta[property="og:image"]').attr('content') || $('meta[name="og:image"]').attr('content');
    return og && og.startsWith('http') ? og : undefined;
  } catch {
    return undefined;
  }
}

async function main() {
  const apply = process.argv.includes('--apply');
  const rows = await prisma.news.findMany({
    where: { autoGenerated: true, source: 'MAVS_MONEYBALL', imageUrl: null, sourceUrl: { not: '' } },
    select: { id: true, title: true, sourceUrl: true },
  });
  console.log(`대상 ${rows.length}건 (apply=${apply})`);
  let filled = 0, miss = 0;
  for (const r of rows) {
    const img = await ogImage(r.sourceUrl);
    if (img) {
      filled++;
      console.log(`  ✓ ${r.title.slice(0, 30)} → ${img.slice(0, 70)}`);
      if (apply) await prisma.news.update({ where: { id: r.id }, data: { imageUrl: img } });
    } else {
      miss++;
      console.log(`  ✗ ${r.title.slice(0, 30)} (og:image 없음)`);
    }
  }
  console.log(`\n결과: 채움 ${filled} / 실패 ${miss} / 전체 ${rows.length}${apply ? ' (DB 반영됨)' : ' (dry-run, --apply로 반영)'}`);
}

main().finally(() => prisma.$disconnect());
